public class Repository<T, TKey> where T : class, IEntity<TKey>, new()
                                   where TKey : notnull
{
    private readonly List<T> _items = new();

    public T Create() => new T();

    public T? GetById(TKey id) => _items.FirstOrDefault(x => x.Id.Equals(id));

