// PROPER PATTERNS: Avoid async void, use CancellationToken, handle exceptions
public class AsyncBestPractices
{
    // BAD: async void — exceptions crash the process, cannot be awaited
    // public async void BadMethod() { }

    // GOOD: Return Task, accept CancellationToken
    public async Task ProcessBatchAsync(
        IEnumerable<Item> items, 
        CancellationToken ct = default)
    {
        // ConfigureAwait(false) in libraries — don't capture SynchronizationContext
        var data = await FetchDataAsync().ConfigureAwait(false);

        // Parallel async with constrained concurrency
        var semaphore = new SemaphoreSlim(10);
        var tasks = items.Select(async item =>
        {
            await semaphore.WaitAsync(ct);
            try { await ProcessItemAsync(item, ct); }
            finally { semaphore.Release(); }
        });

        await Task.WhenAll(tasks);
    }

    // Fire-and-forget with proper exception handling
    public void TriggerBackgroundWork()
    {
        _ = BackgroundWorkAsync().ContinueWith(t =>
        {
            if (t.IsFaulted)
                _logger.LogError(t.Exception, "Background work failed");
        }, TaskScheduler.Default);
    }
}

