public class OrderRepository
{
    private readonly AppDbContext _db;
    public OrderRepository(AppDbContext db) => _db = db;

    public record OrderDto(Guid Id, decimal Total, int ItemCount);
    public record MonthlyReport(int Month, decimal Revenue);

    public async Task<List<OrderDto>> GetCustomerOrdersAsync(Guid customerId)
    {
        // EAGER LOADING + PROJECTION: Fetch only needed columns, reduce network traffic
        return await _db.Orders
            .AsNoTracking() // Skip change tracking for read-only scenarios
            .Where(o => o.CustomerId == customerId)
            .Include(o => o.OrderItems)
            .Select(o => new OrderDto
            (
                o.Id,
                o.OrderItems.Sum(i => i.Quantity * i.UnitPrice),
                o.OrderItems.Count
            ))
            .ToListAsync();
    }

    // COMPILED QUERY: Pre-compiled LINQ for hot paths (EF Core 6+)
    private static readonly Func<AppDbContext, Guid, Task<Order?>> GetOrderByIdQuery =
        EF.CompileAsyncQuery((AppDbContext db, Guid id) =>
            db.Orders.AsNoTracking().FirstOrDefault(o => o.Id == id));

    public Task<Order?> GetOrderFastAsync(Guid id) => GetOrderByIdQuery(_db, id);

    // RAW SQL for complex reports
    public async Task<List<MonthlyReport>> GetMonthlyReportAsync(int year)
    {
        var yearParam = new SqlParameter("@year", year);
        return await _db.Database
            .SqlQueryRaw<MonthlyReport>(
                "SELECT Month, SUM(Total) as Revenue FROM Orders WHERE Year = @year GROUP BY Month",
                yearParam)
            .ToListAsync();
    }
}

