using System.Net;
using Polly;
using Polly.Retry;
using Microsoft.Extensions.Logging;

public class ResilientApiClient
{
    private readonly HttpClient _httpClient;
    private readonly ILogger<ResilientApiClient> _logger;
    private readonly AsyncRetryPolicy<HttpResponseMessage> _retryPolicy;

    public ResilientApiClient(HttpClient client, ILogger<ResilientApiClient> logger)
    {
        _httpClient = client;
        _logger = logger;

        _retryPolicy = Policy
            .HandleResult<HttpResponseMessage>(r => 
                (int)r.StatusCode >= 500 || r.StatusCode == HttpStatusCode.RequestTimeout)
            .WaitAndRetryAsync(
                retryCount: 3,
                sleepDurationProvider: retryAttempt => 
                    TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)), // Exponential backoff
                onRetry: (outcome, timeSpan, retryCount, context) =>
                {
                    _logger.LogWarning(
                        "Retry {RetryCount} after {Delay}s due to {StatusCode}",
                        retryCount, timeSpan.TotalSeconds, outcome.Result?.StatusCode);
                });
    }

    public async Task<string> GetDataAsync(string url, CancellationToken ct)
    {
        var response = await _retryPolicy.ExecuteAsync(
            () => _httpClient.GetAsync(url, ct));

        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(ct);
    }
}

