// gRPC SERVICE (Contract-first high-performance RPC)
// Domain model and repository stub
public interface IUserRepository { Task<User?> GetByIdAsync(Guid id); }
public class User
{
    public Guid Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
}

// Protobuf contracts (normally generated from .proto files)
[ProtoContract]
public class GetUserRequest
{
    [ProtoMember(1)]
    public Guid UserId { get; set; }
}

[ProtoContract]
public class UserResponse
{
    [ProtoMember(1)] public Guid Id { get; set; }
    [ProtoMember(2)] public string Name { get; set; } = string.Empty;
    [ProtoMember(3)] public string Email { get; set; } = string.Empty;
}

// gRPC service implementation (base class generated from protobuf)
public class UserGrpcService : UserService.UserServiceBase
{
    private readonly IUserRepository _repo;
    public UserGrpcService(IUserRepository repo) => _repo = repo;

    public override async Task<UserResponse> GetUser(
        GetUserRequest request, ServerCallContext context)
    {
        var user = await _repo.GetByIdAsync(request.UserId);
        if (user is null)
            throw new RpcException(new Status(StatusCode.NotFound, "User not found"));

        return new UserResponse 
        { 
            Id = user.Id, 
            Name = user.Name, 
            Email = user.Email 
        };
    }
}
